// External icon hosts are denied by default. A host may be added here only
// after its content is vetted; until then every http(s) icon is dropped so
// rendering an icon can never leak user data (claim links, addresses) to a
// third-party CDN.
const EXTERNAL_ICON_ALLOWLIST = new Set<string>([
  // intentionally empty — every bundled icon is a self-contained data: URI
]);

// Known-bad hosts, denied even if accidentally allowlisted later.
const EXTERNAL_ICON_BLOCKLIST = new Set<string>([
  'https://image.mitte.gg',
]);

function sanitizeIconUrl(icon: string | undefined): string | undefined {
  if (!icon) return undefined;
  if (!/^https?:\/\//i.test(icon)) return icon; // data: URIs are self-contained
  let origin: string;
  try {
    origin = new URL(icon).origin;
  } catch {
    return undefined;
  }
  if (EXTERNAL_ICON_BLOCKLIST.has(origin)) return undefined;
  if (!EXTERNAL_ICON_ALLOWLIST.has(origin)) return undefined;
  return icon;
}

/**
 * Resolves an icon for a token key, contract id, or defuse asset id.
 * Lookup is suffix-normalized: chain prefixes (`nep141:...`) are stripped and
 * first-label suffixes retried so one icon serves every id form.
 */
export function getOnchainIcon(keyOrContract: string): string | undefined {
  if (!keyOrContract) return undefined;
  const k = keyOrContract.toLowerCase();
  const candidates = [k, keyOrContract];
  if (k.includes(':')) candidates.push(k.slice(k.indexOf(':') + 1));
  const firstLabel = k.split('.')[0];
  if (firstLabel.length > 2 && !candidates.includes(firstLabel)) {
    candidates.push(firstLabel);
  }
  for (const key of candidates) {
    const icon = ONCHAIN_TOKEN_ICONS[key];
    if (icon) return sanitizeIconUrl(icon);
  }
  return undefined;
}
